import JKAShared
import JKAMP
import JKAMP_Ded

/// All state of the dedicated server, rule 3, in the shape of `CGameWorld`.
/// One instance exists behind `world`, and the shell builds a fresh one at its entry.
public final class EngineWorld {
    let storage = EngineStorage()
    /// Raven's file-scope variables the engine files write, generated by skeleton.py, reached by Raven's name through the stubs.
    var variables = EngineVariables()
    let strings = StringPool.shared

    /// The shell entry builds a fresh world, so the initializer is public.
    public init() {}
}

/// The one instance. The engine runs one thread, so this is not isolated.
public nonisolated(unsafe) var world = EngineWorld()

/// The string pool of rule 9, the only source of a runtime `char *`.
var strings: StringPool { world.strings }
